import{_ as e,c as a,o as t,a2 as o}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"MediaLibraryController","description":"","frontmatter":{"sidebarPos":15,"sidebarTitle":"MediaLibraryController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/media-library-controller.md","filePath":"system-reference/backend/http/controllers/media-library-controller.md","lastUpdated":1778363927000}'),d={name:"system-reference/backend/http/controllers/media-library-controller.md"},r=o('<h1 id="medialibrarycontroller" tabindex="-1">MediaLibraryController <a class="header-anchor" href="#medialibrarycontroller" aria-label="Permalink to &quot;MediaLibraryController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/MediaLibraryController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>BaseController</code><br><strong>Implements</strong>: <code>SignUploadListener</code></p><p>Manages the media (image) library. Similar to <code>FileLibraryController</code> but stores image dimensions, alt text, captions, and custom metadata fields alongside each uploaded file.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>$moduleName</code></td><td><code>string</code></td><td><code>&#39;Media&#39;</code></td><td>—</td></tr><tr><td><code>$routeName</code></td><td><code>string</code></td><td><code>&#39;Media&#39;</code></td><td>—</td></tr><tr><td><code>$perPage</code></td><td><code>int</code></td><td><code>40</code></td><td>Images per page</td></tr><tr><td><code>$endpointType</code></td><td><code>string</code></td><td>—</td><td><code>&#39;local&#39;</code> or cloud provider key</td></tr><tr><td><code>$customFields</code></td><td><code>array</code></td><td><code>[]</code></td><td>Extra metadata field keys</td></tr><tr><td><code>$defaultFilters</code></td><td><code>array</code></td><td><code>[&#39;search&#39;, &#39;tag&#39;, &#39;unused&#39;]</code></td><td>Active filter keys</td></tr><tr><td><code>$defaultOrders</code></td><td><code>array</code></td><td><code>[[&#39;column&#39; =&gt; &#39;id&#39;, &#39;direction&#39; =&gt; &#39;desc&#39;]]</code></td><td>Default sort</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="index-parentid-null-array" tabindex="-1"><code>index($parentId = null): array</code> <a class="header-anchor" href="#index-parentid-null-array" aria-label="Permalink to &quot;`index($parentId = null): array`&quot;">​</a></h3><p>Returns a paginated media list with tag counts and filter options.</p><h3 id="getindexdata-array-scopes-array" tabindex="-1"><code>getIndexData(array $scopes): array</code> <a class="header-anchor" href="#getindexdata-array-scopes-array" aria-label="Permalink to &quot;`getIndexData(array $scopes): array`&quot;">​</a></h3><p>Returns <code>[&#39;items&#39;, &#39;maxPage&#39;, &#39;total&#39;, &#39;tags&#39;]</code>.</p><h3 id="store-parentid-null-jsonresponse" tabindex="-1"><code>store($parentId = null): JsonResponse</code> <a class="header-anchor" href="#store-parentid-null-jsonresponse" aria-label="Permalink to &quot;`store($parentId = null): JsonResponse`&quot;">​</a></h3><p>Dispatches to <code>storeFile()</code> for local uploads or <code>storeReference()</code> for cloud references.</p><h3 id="storefile-request-request-media" tabindex="-1"><code>storeFile(Request $request): Media</code> <a class="header-anchor" href="#storefile-request-request-media" aria-label="Permalink to &quot;`storeFile(Request $request): Media`&quot;">​</a></h3><p>Handles a local image upload:</p><ol><li>Extracts image dimensions via <code>getimagesize()</code>.</li><li>Sanitises filename and generates a UUID storage path.</li><li>Stores the file on the configured disk.</li><li>Persists the <code>Media</code> record with <code>width</code> and <code>height</code>.</li></ol><h3 id="storereference-request-request-media" tabindex="-1"><code>storeReference(Request $request): Media</code> <a class="header-anchor" href="#storereference-request-request-media" aria-label="Permalink to &quot;`storeReference(Request $request): Media`&quot;">​</a></h3><p>Records a reference to an image stored in cloud storage.</p><h3 id="singleupdate-jsonresponse" tabindex="-1"><code>singleUpdate(): JsonResponse</code> <a class="header-anchor" href="#singleupdate-jsonresponse" aria-label="Permalink to &quot;`singleUpdate(): JsonResponse`&quot;">​</a></h3><p>Updates one media item&#39;s <code>alt_text</code>, <code>caption</code>, <code>tags</code>, and custom fields.</p><h3 id="bulkupdate-jsonresponse" tabindex="-1"><code>bulkUpdate(): JsonResponse</code> <a class="header-anchor" href="#bulkupdate-jsonresponse" aria-label="Permalink to &quot;`bulkUpdate(): JsonResponse`&quot;">​</a></h3><p>Bulk-updates <code>alt_text</code>, <code>caption</code>, and tags across multiple media items. Supports a <code>remove</code> mode that clears a field from all selected items.</p><h3 id="bulkdelete-jsonresponse" tabindex="-1"><code>bulkDelete(): JsonResponse</code> <a class="header-anchor" href="#bulkdelete-jsonresponse" aria-label="Permalink to &quot;`bulkDelete(): JsonResponse`&quot;">​</a></h3><p>Soft-deletes multiple media items.</p><h3 id="signs3upload-request-request-signs3upload-signer-mixed" tabindex="-1"><code>signS3Upload(Request $request, SignS3Upload $signer): mixed</code> <a class="header-anchor" href="#signs3upload-request-request-signs3upload-signer-mixed" aria-label="Permalink to &quot;`signS3Upload(Request $request, SignS3Upload $signer): mixed`&quot;">​</a></h3><p>Signs an S3 pre-signed upload policy.</p><h3 id="signazureupload-request-request-signazureupload-signer-mixed" tabindex="-1"><code>signAzureUpload(Request $request, SignAzureUpload $signer): mixed</code> <a class="header-anchor" href="#signazureupload-request-request-signazureupload-signer-mixed" aria-label="Permalink to &quot;`signAzureUpload(Request $request, SignAzureUpload $signer): mixed`&quot;">​</a></h3><p>Returns an Azure Blob SAS URL.</p><h3 id="uploadissigned-signature-bool-ispublic-false-jsonresponse-response" tabindex="-1"><code>uploadIsSigned($signature, bool $isPublic = false): JsonResponse|Response</code> <a class="header-anchor" href="#uploadissigned-signature-bool-ispublic-false-jsonresponse-response" aria-label="Permalink to &quot;`uploadIsSigned($signature, bool $isPublic = false): JsonResponse|Response`&quot;">​</a></h3><p>Returns the signed URL to the frontend on success.</p><h3 id="uploadisnotvalid-jsonresponse" tabindex="-1"><code>uploadIsNotValid(): JsonResponse</code> <a class="header-anchor" href="#uploadisnotvalid-jsonresponse" aria-label="Permalink to &quot;`uploadIsNotValid(): JsonResponse`&quot;">​</a></h3><p>Returns an error on signing failure.</p><h3 id="shouldreplacemedia-id-bool" tabindex="-1"><code>shouldReplaceMedia($id): bool</code> <a class="header-anchor" href="#shouldreplacemedia-id-bool" aria-label="Permalink to &quot;`shouldReplaceMedia($id): bool`&quot;">​</a></h3><p>Returns <code>true</code> when the given ID matches an existing media record (replacement flow).</p><h3 id="getextrametadatas-collection" tabindex="-1"><code>getExtraMetadatas(): Collection</code> <a class="header-anchor" href="#getextrametadatas-collection" aria-label="Permalink to &quot;`getExtraMetadatas(): Collection`&quot;">​</a></h3><p>Extracts values for <code>$customFields</code> from the current request and returns them as a keyed collection.</p><h2 id="custom-fields" tabindex="-1">Custom Fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom Fields&quot;">​</a></h2><p>Define additional metadata fields per deployment by setting <code>$customFields</code> on a subclass:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">protected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $customFields </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;photographer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;license&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>These fields are extracted from the request in <code>getExtraMetadatas()</code> and persisted alongside the media record.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./file-library-controller">FileLibraryController</a> — non-image file variant</li><li><a href="./glide-controller">GlideController</a> — serves transformed images from this library</li><li><a href="./filepond-controller">FilepondController</a> — temporary upload handler</li></ul>',41),s=[r];function i(l,n,c,p,u,h){return t(),a("div",null,s)}const b=e(d,[["render",i]]);export{g as __pageData,b as default};
